package ai.decisionos.aside;
import android.app.*;import android.widget.*;import org.json.*;
/** Only a native human review dialog can dispatch the reviewed Outlook draft. */
final class CampusMailReview {
 static void call(GoalChatUi c,JSONObject body,GoalAgentRelay.Response reply){if(!c.a.relay.connected()){c.a.pair();return;}GoalStore.put(body,"device_session",c.a.relay.session());c.a.relay.chat("/campus-actions",body,reply);}
 static void show(GoalChatUi c){call(c,new GoalChatUi.JSONObjectSafe("action","list"),r->{if(r.has("error")){c.a.toast(r.optString("error"));return;}JSONArray items=r.optJSONArray("items");if(items==null||items.length()==0){new AlertDialog.Builder(c.a).setTitle("보낼 메일 검토").setMessage("아직 발송 검토에 준비된 메일이 없어요. 똑똑이에게 수신자가 지정된 임시저장 메일의 발송 준비를 요청해 주세요. 학교 메일 웹 로그인과 Graph 발송 권한 연결은 별개예요.").setPositiveButton("확인",null).show();return;}String[] labels=new String[items.length()];for(int n=0;n<items.length();n++){JSONObject x=items.optJSONObject(n);labels[n]=x.optString("state")+" · "+x.optJSONObject("message").optString("subject");}new AlertDialog.Builder(c.a).setTitle("메일 발송 검토").setItems(labels,(d,n)->load(c,items.optJSONObject(n))).setNegativeButton("닫기",null).show();});}
 static void load(GoalChatUi c,JSONObject item){JSONObject body=new GoalChatUi.JSONObjectSafe("action","get");GoalStore.put(body,"id",item.optString("id"));call(c,body,r->{if(r.has("error"))c.a.toast(r.optString("error"));else review(c,r);});}
 static void review(GoalChatUi c,JSONObject item){JSONObject m=item.optJSONObject("message");String text="받는 사람\n"+m.optJSONObject("recipients")+"\n\n제목\n"+m.optString("subject")+"\n\n본문\n"+m.optJSONObject("body").optString("content")+"\n\n첨부\n"+m.optJSONArray("attachments")+"\n\n상태: "+item.optString("state")+"\n"+item.optString("reason","");TextView v=c.a.txt(text,14,NubiCompanionUi.INK,false);v.setPadding(Ui.dp(c.a,18),Ui.dp(c.a,12),Ui.dp(c.a,18),Ui.dp(c.a,12));v.setTextIsSelectable(true);ScrollView scroll=new ScrollView(c.a);scroll.addView(v);AlertDialog.Builder b=new AlertDialog.Builder(c.a).setTitle("이 내용으로 보낼까요?").setView(scroll).setNegativeButton("닫기",null);if(item.optString("state").equals("review")){b.setPositiveButton("확인하고 발송",(d,w)->{JSONObject body=new GoalChatUi.JSONObjectSafe("action","send");GoalStore.put(body,"id",item.optString("id"));GoalStore.put(body,"digest",item.optString("digest"));call(c,body,r->{String msg=r.has("error")?r.optString("error"):r.optString("state").equals("accepted")?"발송 요청이 접수됐어요. 수신자 도착은 아직 확인되지 않았어요.":"발송 결과가 미확인이에요. 보낸 편지함을 먼저 확인해 주세요.";new AlertDialog.Builder(c.a).setTitle("메일 발송 상태").setMessage(msg).setPositiveButton("확인",null).show();});});b.setNeutralButton("발송 취소",(d,w)->{JSONObject body=new GoalChatUi.JSONObjectSafe("action","cancel");GoalStore.put(body,"id",item.optString("id"));call(c,body,r->c.a.toast(r.has("error")?r.optString("error"):"발송 준비를 취소했어요."));});}b.show();}
}
